# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

KANBAN_STATES = [
    "DISCOVER",
    "READY",
    "EXECUTION",
    "REVIEW",
    "RELEASE",
    "COMPLETE",
]

KANBAN_TRANSITIONS: dict[str, list[str]] = {
    "DISCOVER": ["READY"],
    "READY": ["EXECUTION"],
    "EXECUTION": ["REVIEW"],
    "REVIEW": ["READY", "RELEASE"],
    "RELEASE": ["COMPLETE"],
}


# ---------------------------------------------------------------------------
# State File I/O
# ---------------------------------------------------------------------------

def _state_path(project_dir: str) -> str:
    return _ss.state_path(project_dir)


def _resolve_spec_id(spec_id: str | None) -> str | None:
    if spec_id:
        return spec_id
    env = os.environ.get("SYNAPTORY_ACTIVE_SPEC")
    return env if env else None


def _default_state() -> dict[str, Any]:
    return {
        "version": product_version(), "state_schema": 2,
        "build_mode": "kanban",
        "lifecycle_state": "DISCOVER",
        "started_at": _now(),
        "lifecycle_history": [
            {"state": "DISCOVER", "entered_at": _now(), "exited_at": None},
        ],
        "tickets_completed": [],
        "current_stories": [],
        "cumulative_ticket_number": 0,
        "agent_backends": {
            "default": host_env.default_agent_backend(),
            "roles": {},
        },
        "transitioned_from": None,
    }


def _default_spec_substate() -> dict[str, Any]:
    s = _default_state()
    s.pop("version", None)
    s.pop("state_schema", None)
    s.pop("build_mode", None)
    return s


def read_state(project_dir: str, spec_id: str | None = None) -> dict[str, Any]:
    """Read pipeline state. Raises ValueError if not Kanban format."""
    sid = _resolve_spec_id(spec_id)
    full = _ss.read_full_state(project_dir)
    if not full:
        return _default_state()

    if _ss.is_multispec(full):
        # In multi-spec mode, `build_mode` lives at the top level —
        # validate there, then return the spec's flat sub-state.
        mode = full.get("build_mode", "unknown")
        if mode != "kanban":
            raise ValueError(
                f"State is not Kanban format (found: {mode}). "
                "Use scrum_state_machine.py for Scrum, or transition_to_kanban first."
            )
        return _ss.read_state(
            project_dir, spec_id=sid,
            default_state_factory=_default_spec_substate,
        )

    # v2 flat layout
    if full.get("build_mode") != "kanban":
        mode = full.get("build_mode", "unknown")
        raise ValueError(
            f"State is not Kanban format (found: {mode}). "
            "Use scrum_state_machine.py for Scrum, or transition_to_kanban first."
        )
    return full


def _write_state(project_dir: str, state: dict[str, Any]) -> None:
    _ss.write_state(project_dir, state)


# ---------------------------------------------------------------------------
# Lifecycle Management
# ---------------------------------------------------------------------------

def initialize(
    project_dir: str,
    agent_backends: dict[str, Any] | None = None,
    spec_id: str | None = None,
) -> dict[str, Any]:
    """Initialize Kanban state at DISCOVER.

    Single-spec: writes a flat v2.0 file.
    Multi-spec:  initializes `specs[<spec_id>]` in the existing v3 file.
    """
    sid = _resolve_spec_id(spec_id)
    full = _ss.read_full_state(project_dir)

    if sid:
        if not full:
            full = {"version": product_version(), "state_schema": 3, "build_mode": "kanban",
                    "active_spec": sid, "specs": {}}
        elif state_schema(full) == 2:
            raise ValueError(
                "Cannot initialize a v3 spec slot in a v2 file. Run the "
                "migration script (migrate_to_multispec.py) first."
            )
        sub = _default_spec_substate()
        if agent_backends:
            sub["agent_backends"] = agent_backends
        full.setdefault("specs", {})[sid] = sub
        if not full.get("active_spec"):
            full["active_spec"] = sid
        full["build_mode"] = "kanban"
        _ss.write_full_state(project_dir, full)
        view = dict(sub)
        view["_spec_id"] = sid
        view["_multispec"] = True
        return view

    state = _default_state()
    if agent_backends:
        state["agent_backends"] = agent_backends
    _write_state(project_dir, state)
    return state


def transition(
    project_dir: str,
    to_state: str,
    force: bool = False,
) -> dict[str, Any]:
    """Transition lifecycle to a new state.

    Raises:
        ValueError: On illegal transition.
    """
    state = read_state(project_dir)
    current = state["lifecycle_state"]

    if current == "COMPLETE":
        raise ValueError("Cannot transition from COMPLETE — lifecycle is finished")

    if to_state not in KANBAN_STATES:
        raise ValueError(f"Invalid state: {to_state}. Must be one of {KANBAN_STATES}")

    if not force and to_state not in KANBAN_TRANSITIONS.get(current, []):
        raise ValueError(
            f"Illegal transition: {current} → {to_state}. "
            f"Valid targets: {KANBAN_TRANSITIONS.get(current, [])}"
        )

    now = _now()

    if state["lifecycle_history"]:
        state["lifecycle_history"][-1]["exited_at"] = now

    state["lifecycle_state"] = to_state
    state["lifecycle_history"].append(
        {"state": to_state, "entered_at": now, "exited_at": None}
    )

    _write_state(project_dir, state)
    return state


def get_lifecycle_state(project_dir: str) -> str:
    """Return current lifecycle state string."""
    state = read_state(project_dir)
    return state["lifecycle_state"]


# ---------------------------------------------------------------------------
# Ticket Management
# ---------------------------------------------------------------------------

def pull_ticket(
    project_dir: str,
    ticket_id: str,
    title: str = "",
    backends: dict[str, str] | None = None,
    acceptance_criteria: list[Any] | None = None,
    kind: str = "",
    labels: list[str] | None = None,
    depends_on: list[str] | None = None,
    file_scope: list[str] | None = None,
) -> dict[str, Any]:
    """Pull a ticket into the board.

    Adds to current_stories in queued state. Increments cumulative counter.
    """
    state = read_state(project_dir)

    story = create_story(
        ticket_id, title, backends, acceptance_criteria=acceptance_criteria,
        # #134 — kind/labels/depends_on/file_scope flow through exactly like
        # the scrum start_sprint path.
        kind=kind, labels=labels, depends_on=depends_on, file_scope=file_scope,
        project_dir=project_dir,
    )
    state.setdefault("current_stories", []).append(story)
    state["cumulative_ticket_number"] = state.get("cumulative_ticket_number", 0) + 1

    _write_state(project_dir, state)
    return state


def complete_ticket(project_dir: str, ticket_id: str) -> dict[str, Any]:
    """Move a completed ticket from current_stories to tickets_completed.

    Calculates cycle time and records DoD result.
    """
    state = read_state(project_dir)

    story = get_story(state, ticket_id)
    if story is None:
        raise ValueError(f"Ticket not found: {ticket_id}")
    if story.get("state") != "done":
        raise ValueError(
            f"Ticket {ticket_id} is not done (state: {story.get('state')}). "
            "Complete the pipeline first."
        )

    # Calculate cycle time.
    ct = calculate_story_cycle_time(story)
    cycle_seconds = ct["total_seconds"] if ct else 0.0

    # Build completion record.
    ticket_record: dict[str, Any] = {
        "id": ticket_id,
        "title": story.get("title", ""),
        "completed_at": _now(),
        "cycle_time_seconds": round(cycle_seconds, 1),
        "dod": story.get("dod"),
    }
    state.setdefault("tickets_completed", []).append(ticket_record)

    # Remove from current_stories.
    state["current_stories"] = [
        s for s in state.get("current_stories", []) if s.get("id") != ticket_id
    ]

    _write_state(project_dir, state)
    return state


def transition_story(
    project_dir: str,
    story_id: str,
    to_state: str,
    reason: str | None = None,
) -> dict[str, Any]:
    """Transition a ticket's sub-state.

    On `→ done`, auto-invokes DoD evaluation so the ticket record always
    carries a `dod` field by the time complete_ticket runs (see #104).
    """
    state = read_state(project_dir)

    # #31/#30: hold a PHI/healthcare ticket (or one in a runtime_verification-
    # required project) out of `done` until its conditional compliance/runtime
    # gates pass; redirect the `reviewing → done` promotion to `blocked`
    # (recoverable) rather than silently completing on green SE/QE/CR.
    if to_state == "done":
        # Delegated to the shared kernel (#277). resolve_done_edge reproduces
        # this mode's ticket-number intensity and its deliberate absence of a
        # PO acceptance redirect.
        from advance_kernel import resolve_done_edge

        to_state, reason, _pre_dod = resolve_done_edge(
            project_dir, state, story_id, to_state, reason, mode="kanban"
        )
    else:
        _pre_dod = None

    state = _sp_transition_story(state, story_id, to_state, reason, project_dir)
    _write_state(project_dir, state)

    # #403 — same as the scrum path: a gate-blocked ticket recorded no DoD
    # verdict and shipped nothing, so the reason it stopped never left the
    # machine. resolve_done_edge already computed it.
    if to_state == "blocked" and _pre_dod is not None:
        story = get_story(state, story_id)
        if story:
            story["dod"] = _pre_dod
            _write_state(project_dir, state)
            _sp_ship_evaluated_dod(story_id, _pre_dod, project_dir=project_dir)

    if to_state == "done":
        ticket_num = state.get("cumulative_ticket_number", 1)
        intensity = determine_dod_intensity(ticket_number=ticket_num)
        result = _sp_evaluate_dod(project_dir, story_id, intensity)
        story = get_story(state, story_id)
        if story:
            story["dod"] = result
            _write_state(project_dir, state)
            _sp_ship_evaluated_dod(
                story_id, result, project_dir=project_dir
            )   # #199

    return state


def evaluate_ticket_dod(project_dir: str, ticket_id: str) -> dict[str, Any]:
    """Evaluate per-ticket DoD. Uses cumulative_ticket_number for intensity."""
    state = read_state(project_dir)
    ticket_num = state.get("cumulative_ticket_number", 1)
    intensity = determine_dod_intensity(ticket_number=ticket_num)
    result = _sp_evaluate_dod(project_dir, ticket_id, intensity)

    # Store result in state.
    story = get_story(state, ticket_id)
    if story:
        story["dod"] = result
        _write_state(project_dir, state)
        _sp_ship_evaluated_dod(
            ticket_id, result, project_dir=project_dir
        )   # #199

    return result


def next_action(project_dir: str) -> dict[str, Any]:
    """Lifecycle-aware "what's next" for the kanban loop (epic #75, P1).

    Mirror of scrum_state_machine.next_action: outside EXECUTION the board
    is not dispatchable, so the orchestrator (and the P2 Stop-hook loop
    engine) get `not_in_execution` instead of a story action. Read-only.

    Passes `dod_tier_info` and `parallelism` for the same reason the scrum
    wrapper does (see its docstring): `modes/kanban.md` drives the loop
    through this wrapper, so omitting them made story parallelism
    unreachable and discarded an explicitly recorded DoD tier. Both
    resolvers are pure reads.
    """
    state = read_state(project_dir)
    lifecycle = state.get("lifecycle_state", "DISCOVER")
    base = {
        "lifecycle_state": lifecycle,
        "cumulative_ticket_number": state.get("cumulative_ticket_number", 0),
        "spec_id": state.get("_spec_id"),
    }
    if lifecycle != "EXECUTION":
        return {
            **base,
            "action": "not_in_execution",
            "story_id": None,
            "reason": (
                f"lifecycle is {lifecycle}, not EXECUTION — tickets are only "
                "dispatched during execution"
            ),
            "human_gate_pending": False,
        }
    result = _sp_next_action(
        state,
        per_story_acceptance=is_per_story_acceptance_enabled(project_dir),
        receipts_dir=_resolve_receipts_dir(project_dir),
        verification_loops=verification_loops_active(project_dir),
        dod_tier_info=resolve_dod_tier(project_dir, state),
        parallelism=parallelism_config(project_dir),
        dep_context=dep_context(project_dir, state),
        dependency_gate=dependency_gate_mode(project_dir),
        verify_only=verify_only_units(project_dir, state),
        inadmissible_receipts=advance_kernel.inadmissible_receipts(project_dir, state),
    )
    # #501 follow-up — swap the tier-only `dod` block for the per-story
    # contract the gate will actually enforce. Lives here, not in
    # `story_pipeline.next_action`, which has no project_dir and stays pure.
    attach_dispatch_dod_contract(
        result,
        project_dir,
        state=state,
        receipts_dir=_resolve_receipts_dir(project_dir),
    )
    # #820 -- a disabled continuation loop is named on the dispatch contract.
    # `loop_engine.attach_loop_status` is the one predicate; re-deriving the
    # kill switches per lifecycle is how one of the three would come to
    # disagree with the engine that actually stops.
    import loop_engine as _loop

    _loop.attach_loop_status(result, project_dir)
    result.update(base)
    return result


# ---------------------------------------------------------------------------
# Metrics
# ---------------------------------------------------------------------------

def calculate_throughput(
    project_dir: str, window_days: int = 7
) -> dict[str, Any]:
    """Calculate throughput (tickets/day) over a sliding window."""
    state = read_state(project_dir)
    completed = state.get("tickets_completed", [])

    if not completed:
        return {
            "window_days": window_days,
            "tickets_completed": 0,
            "throughput_per_day": 0.0,
            "avg_cycle_time_seconds": 0.0,
        }

    cutoff = datetime.now(timezone.utc) - timedelta(days=window_days)
    recent = []
    for t in completed:
        completed_at = t.get("completed_at", "")
        try:
            ts = datetime.fromisoformat(completed_at.replace("Z", "+00:00"))
            if ts >= cutoff:
                recent.append(t)
        except (ValueError, TypeError):
            pass

    cycle_times = [t.get("cycle_time_seconds", 0) for t in recent if t.get("cycle_time_seconds")]
    avg_ct = sum(cycle_times) / len(cycle_times) if cycle_times else 0.0

    return {
        "window_days": window_days,
        "tickets_completed": len(recent),
        "throughput_per_day": round(len(recent) / window_days, 2) if window_days > 0 else 0.0,
        "avg_cycle_time_seconds": round(avg_ct, 1),
    }


def get_board_summary(project_dir: str) -> dict[str, Any]:
    """Return Kanban board state summary."""
    state = read_state(project_dir)
    stories = state.get("current_stories", [])

    by_state: dict[str, int] = {}
    for s in stories:
        st = s.get("state", "unknown")
        by_state[st] = by_state.get(st, 0) + 1

    tp = calculate_throughput(project_dir)

    return {
        "lifecycle_state": state["lifecycle_state"],
        "board": by_state,
        "current_tickets": len(stories),
        "cumulative_tickets": state.get("cumulative_ticket_number", 0),
        "tickets_completed_total": len(state.get("tickets_completed", [])),
        "throughput_7d": tp["throughput_per_day"],
        "avg_cycle_time_seconds": tp["avg_cycle_time_seconds"],
    }


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main() -> None:
    if len(sys.argv) < 3:
        print("Usage: python3 kanban_state_machine.py <action> <project_dir> [args]", file=sys.stderr)
        sys.exit(1)

    action = sys.argv[1]
    project_dir = sys.argv[2]
    args = sys.argv[3:]

    # Multi-spec: consume --spec=<id> and set SYNAPTORY_ACTIVE_SPEC so internal
    # read_state/_write_state calls route to the named spec's slot.
    args, spec_id_flag = _consume_spec_flag(args)
    if spec_id_flag:
        os.environ["SYNAPTORY_ACTIVE_SPEC"] = spec_id_flag

    try:
        if action == "init":
            backends_json = _parse_flag(args, "--backends", None)
            backends = json.loads(backends_json) if backends_json else None
            result = initialize(project_dir, backends)
            print(json.dumps(result, indent=2))

        elif action == "read":
            result = read_state(project_dir)
            print(json.dumps(result, indent=2))

        elif action == "transition":
            if not args:
                _die("Usage: transition <project_dir> <to_state> [--force]")
            to_state = args[0]
            force = "--force" in args
            result = transition(project_dir, to_state, force)
            print(json.dumps(result, indent=2))

        elif action == "pull_ticket":
            if not args:
                _die("Usage: pull_ticket <project_dir> <ticket_id> [--title '...'] [--backends '{...}'] [--acceptance-criteria '[...]']")
            ticket_id = args[0]
            title = _parse_flag(args, "--title", "")
            backends_json = _parse_flag(args, "--backends", None)
            backends = json.loads(backends_json) if backends_json else None
            # #44: pass ACs through so create_story snapshots them and derives
            # `ui_bearing`. A ticket whose UI signal lives only in its ACs
            # (e.g. "when the user opens the dashboard, the UI renders") with a
            # non-UI title must still promote the ui_acceptance gate; dropping
            # ACs here let it reach `done` on backend-only receipts.
            acs_json = _parse_flag(args, "--acceptance-criteria", None)
            acceptance_criteria = json.loads(acs_json) if acs_json else None

            def _json_flag(flag: str) -> Any:
                raw = _parse_flag(args, flag, None)
                return json.loads(raw) if raw else None

            result = pull_ticket(
                project_dir, ticket_id, title, backends,
                acceptance_criteria=acceptance_criteria,
                # #134 — story metadata for tier scoping + parallel dispatch.
                kind=_parse_flag(args, "--kind", ""),
                labels=_json_flag("--labels"),
                depends_on=_json_flag("--depends-on"),
                file_scope=_json_flag("--file-scope"),
            )
            print(json.dumps(result, indent=2))

        elif action == "complete_ticket":
            if not args:
                _die("Usage: complete_ticket <project_dir> <ticket_id>")
            result = complete_ticket(project_dir, args[0])
            print(json.dumps(result, indent=2))

        elif action == "transition_story":
            if len(args) < 2:
                _die(
                    "Usage: transition_story <project_dir> <story_id> <to_state> "
                    "[--reason '...'] [--force-recovery]"
                )
            story_id, to_state = args[0], args[1]
            reason = _parse_flag(args, "--reason", None)
            forced = "--force-recovery" in args
            from_state = str(
                (get_story(read_state(project_dir), story_id) or {}).get("state") or ""
            )
            refused = _cli_receipt_gated_refusal(
                from_state,
                to_state,
                story_id,
                forced=forced,
                reason=reason,
                project_dir=project_dir,
            )
            if refused:
                _die(refused)
            result = transition_story(project_dir, story_id, to_state, reason)
            print(json.dumps(result, indent=2))

        elif action == "evaluate_dod":
            if not args:
                _die("Usage: evaluate_dod <project_dir> <ticket_id>")
            result = evaluate_ticket_dod(project_dir, args[0])
            print(json.dumps(result, indent=2))

        elif action == "next_action":
            # Loop Engineering P1 (epic #75): deterministic dispatch for
            # the kanban ticket loop.
            print(json.dumps(next_action(project_dir), indent=2))

        elif action == "throughput":
            window = int(_parse_flag(args, "--window", "7"))
            result = calculate_throughput(project_dir, window)
            print(json.dumps(result, indent=2))

        elif action == "summary":
            result = get_board_summary(project_dir)
            print(json.dumps(result, indent=2))

        else:
            _die(f"Unknown action: {action}")

    except ValueError as e:
        print(json.dumps({"error": str(e)}), file=sys.stderr)
        sys.exit(1)


def _parse_flag(args: list[str], flag: str, default: Any) -> Any:
    """Read `--flag value` or `--flag=value` from args; return string or default."""
    for i, a in enumerate(args):
        if a == flag and i + 1 < len(args):
            return args[i + 1]
        if a.startswith(flag + "="):
            return a.split("=", 1)[1]
    return default


def _consume_spec_flag(args: list[str]) -> tuple[list[str], str | None]:
    """Strip `--spec <id>` / `--spec=<id>` from args; return (clean_args, value)."""
    out: list[str] = []
    value: str | None = None
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--spec" and i + 1 < len(args):
            value = args[i + 1]
            i += 2
            continue
        if a.startswith("--spec="):
            value = a.split("=", 1)[1]
            i += 1
            continue
        out.append(a)
        i += 1
    return out, value


def _die(msg: str) -> None:
    print(msg, file=sys.stderr)
    sys.exit(1)

def verify_only_units(project_dir: str, state: dict) -> "frozenset[str]":
    """Kanban's view of #495 P2's verify-only Work Units.

    DELEGATED, NOT COPIED. Both lifecycles ask the identical question of the
    identical on-disk record, and the tracker-backend section of this repo is
    the standing lesson about what a second copy of one rule costs. The
    definition lives with Scrum only because that module is where it was needed
    first; nothing about it is Scrum-shaped.
    """
    from scrum_state_machine import verify_only_units as _shared

    return _shared(project_dir, state)


if __name__ == "__main__":
    main()
